<?php

namespace nyu\Shell;

use nyu\Access\Checker;
use nyu\App\Controller;

/**
 * The spec of a Run generated by makerun, runs/<App>/runspec.json: what the
 * questions of "makerun crudlRun" answered, and all the generator reads
 * (see RunMaker). Its keys:
 *
 *   appsName  the name of the Run: letters and digits, a letter first
 *   database  the label of its database, '' for the default one
 *   tableRef  its table
 *   idColumn  the key of the table
 *   fieldSet  the fields read and written, each with its format (Tools\Variable,
 *             '' for a value kept as sent); a name ending with ! is required by create
 *   actnList  the actions kept, among index, view, create, update, remove
 *   minmRole  the least role of every action (Checker::ROLE_LIST)
 *   runMount  where the preset serves its routes, the name in lower case by default
 *   childSet  the child tables, by name: linkedBy (the field naming the record),
 *             fieldSet, sortedBy (a field, ^ before it for the reverse order, or ''),
 *             ownRoute (GET <id>/<child>) and listsToo (nested in index too)
 */
class RunSpec{

	// The keys of a spec, and those of each of its children
	const KEYS_LIST = Array('appsName', 'database', 'tableRef', 'idColumn', 'fieldSet', 'actnList', 'minmRole', 'runMount', 'childSet');
	const CHLD_KEYS = Array('linkedBy', 'fieldSet', 'sortedBy', 'ownRoute', 'listsToo');
	// The actions a Run may keep, in the order they are written
	const ACTN_LIST = Array('index', 'view', 'create', 'update', 'remove');
	// The file of the spec, in the folder of the Run
	const SPEC_FILE = 'runspec.json';

	/**
	 * Reads the spec of a Run and checks it.
	 *
	 * @param String $runsFldrPath Folder holding the Runs.
	 * @param String $appsNameText Name of the Run, whatever its case.
	 * @return Array The spec.
	 *
	 * @throws \RuntimeException When the Run, its spec or a value of it is not valid.
	 */
	public static function readSpecsArray( String $runsFldrPath, String $appsNameText ): Array {
		$fldName = Controller::runFoldrString($appsNameText, $runsFldrPath);
		if( $fldName==='' ){
			throw new \RuntimeException('No Run is named '.json_encode($appsNameText));
		}
		$specPth = $runsFldrPath.DS.$fldName.DS.self::SPEC_FILE;
		if( !is_file($specPth) ){
			throw new \RuntimeException('The Run '.$fldName.' has no '.self::SPEC_FILE.': it was not generated by makerun');
		}
		$specArr = json_decode( strval(file_get_contents($specPth)), true );
		if( !is_array($specArr) ){
			throw new \RuntimeException($fldName.'/'.self::SPEC_FILE.' is not valid JSON');
		}
		$flawTxt = self::checkSpecFlaws($specArr);
		if( $flawTxt!=='' ){
			throw new \RuntimeException($fldName.'/'.self::SPEC_FILE.': '.$flawTxt);
		}
		return $specArr;
	}

	/**
	 * Writes the spec of a Run in its folder, created when missing.
	 *
	 * @param String $runsFldrPath Folder holding the Runs.
	 * @param Array  $runSpecArray The spec, checked.
	 * @return String Full path of the file written.
	 *
	 * @throws \RuntimeException When the spec is not valid, or cannot be written.
	 */
	public static function writeSpecsFile( String $runsFldrPath, Array $runSpecArray ): String {
		$flawTxt = self::checkSpecFlaws($runSpecArray);
		if( $flawTxt!=='' ){
			throw new \RuntimeException('Spec not written: '.$flawTxt);
		}
		$runFldr = $runsFldrPath.DS.$runSpecArray['appsName'];
		if( !is_dir($runFldr) && !@mkdir($runFldr, 0775, true) ){
			throw new \RuntimeException('Spec not written: the folder of the Run cannot be made');
		}
		// No child is an object, not a list
		$jsonVal = $runSpecArray;
		if( empty($jsonVal['childSet']) ){
			$jsonVal['childSet'] = new \stdClass();
		}
		$specPth = $runFldr.DS.self::SPEC_FILE;
		(new ConfFile( TOP_DIR.DS.'temp'.DS.'archives' ))->saveFileAtomic($specPth, RunMaker::tabbedJsonText($jsonVal));
		return $specPth;
	}

	/**
	 * Lists the Runs that have a spec, with what it says of them.
	 *
	 * @param String $runsFldrPath Folder holding the Runs.
	 * @return Array A row for each: its name, database, table, actions and children, or the flaw of its spec.
	 */
	public static function listSpecsArray( String $runsFldrPath ): Array {
		$rowList = Array();
		foreach( (array)glob($runsFldrPath.DS.'*'.DS.self::SPEC_FILE) as $onePth ){
			$fldName = basename(dirname(strval($onePth)));
			try{
				$specArr = self::readSpecsArray($runsFldrPath, $fldName);
				$rowList[] = Array($fldName, ($specArr['database']==='') ? '(default)' : $specArr['database'], $specArr['tableRef'], implode(', ', $specArr['actnList']), implode(', ', array_keys($specArr['childSet'])));
			}catch( \RuntimeException $e ){
				$rowList[] = Array($fldName, '', '', '', 'not valid: '.$e->getMessage());
			}
		}
		return $rowList;
	}

	/**
	 * Checks a spec: its keys, and each of its values.
	 *
	 * @param Array $runSpecArray The spec.
	 * @return String The first flaw found, or '' when there is none.
	 */
	public static function checkSpecFlaws( Array $runSpecArray ): String {
		$keyList = array_keys($runSpecArray);
		if( array_diff(self::KEYS_LIST, $keyList) || array_diff($keyList, self::KEYS_LIST) ){
			return 'the keys must be '.implode(', ', self::KEYS_LIST);
		}
		// The name goes into a folder and a namespace : a letter first
		if( !is_string($runSpecArray['appsName']) || !preg_match('/^[A-Za-z][A-Za-z0-9]*$/D', $runSpecArray['appsName']) ){
			return 'appsName must be letters and digits, a letter first';
		}
		if( !is_string($runSpecArray['database']) || !preg_match('/^\w*$/D', $runSpecArray['database']) ){
			return 'database must be the label of a database, or empty';
		}
		foreach( Array('tableRef', 'idColumn') as $oneKey ){
			if( !is_string($runSpecArray[$oneKey]) || !preg_match('/^\w+$/D', $runSpecArray[$oneKey]) ){
				return $oneKey.' must be a plain name';
			}
		}
		$fldFlaw = self::checkFieldsSet($runSpecArray['fieldSet'], true);
		if( $fldFlaw!=='' ){
			return 'fieldSet '.$fldFlaw;
		}
		if( isset($runSpecArray['fieldSet'][$runSpecArray['idColumn']]) || isset($runSpecArray['fieldSet'][$runSpecArray['idColumn'].'!']) ){
			return 'fieldSet must not hold the key, which is never written';
		}
		$actList = $runSpecArray['actnList'];
		if( !is_array($actList) || empty($actList) || !array_is_list($actList) || array_diff($actList, self::ACTN_LIST) || count(array_unique($actList))!=count($actList) ){
			return 'actnList must list some of '.implode(', ', self::ACTN_LIST).', once each';
		}
		if( !in_array($runSpecArray['minmRole'], Checker::ROLE_LIST, true) ){
			return 'minmRole must be one of '.implode(', ', Checker::ROLE_LIST);
		}
		if( !is_string($runSpecArray['runMount']) || !preg_match('#^[A-Za-z0-9_\-]+(/[A-Za-z0-9_\-]+)*$#D', $runSpecArray['runMount']) ){
			return 'runMount must be a path of letters, digits, - and _, without slashes around it';
		}
		if( !is_array($runSpecArray['childSet']) || ( !empty($runSpecArray['childSet']) && array_is_list($runSpecArray['childSet']) ) ){
			return 'childSet must hold each child by its table name';
		}
		foreach( $runSpecArray['childSet'] as $oneTbl => $oneSet ){
			$chldFlw = self::checkChildFlaw(strval($oneTbl), $oneSet, $runSpecArray['tableRef']);
			if( $chldFlw!=='' ){
				return 'childSet.'.$oneTbl.' '.$chldFlw;
			}
		}
		return '';
	}

	/**
	 * Checks the fields of the record or of a child: plain names, each with
	 * a format of Tools\Variable or '' for a value kept as sent.
	 *
	 * @param Mixed $fieldsAsSent The fields, by name.
	 * @param Bool  $requiredMark  Whether a name may end with ! (the record; a child is only read).
	 * @return String The flaw, or '' when there is none.
	 */
	protected static function checkFieldsSet( Mixed $fieldsAsSent, Bool $requiredMark ): String {
		if( !is_array($fieldsAsSent) || empty($fieldsAsSent) || array_is_list($fieldsAsSent) ){
			return 'must hold the fields by name, each with its format';
		}
		foreach( $fieldsAsSent as $oneFld => $oneFmt ){
			if( !preg_match($requiredMark ? '/^\w+!?$/D' : '/^\w+$/D', strval($oneFld)) ){
				return 'holds a name that is not a field: '.$oneFld;
			}
			if( !is_string($oneFmt) || ( $oneFmt!=='' && !method_exists(\nyu\Tools\Variable::class, 'formats'.preg_replace('/\(.*$/s', '', $oneFmt)) ) ){
				return 'gives '.rtrim(strval($oneFld), '!').' a format that is not one: '.json_encode($oneFmt);
			}
		}
		return '';
	}

	/**
	 * Checks a child of the spec.
	 *
	 * @param String $childTbleTxt Name of the child table.
	 * @param Mixed  $childSetting What the spec says of it.
	 * @param String $parentTblTxt The table of the Run.
	 * @return String The flaw, or '' when there is none.
	 */
	protected static function checkChildFlaw( String $childTbleTxt, Mixed $childSetting, String $parentTblTxt ): String {
		// A child with its own route is an action named after its table
		if( !preg_match('/^[A-Za-z_]\w*$/D', $childTbleTxt) || $childTbleTxt===$parentTblTxt || in_array(strtolower($childTbleTxt), self::ACTN_LIST, true) ){
			return 'is not a table the Run can follow: a plain name, neither the table of the Run nor an action';
		}
		if( !is_array($childSetting) || array_diff(self::CHLD_KEYS, array_keys($childSetting)) || array_diff(array_keys($childSetting), self::CHLD_KEYS) ){
			return 'must hold '.implode(', ', self::CHLD_KEYS);
		}
		if( !is_string($childSetting['linkedBy']) || !preg_match('/^\w+$/D', $childSetting['linkedBy']) ){
			return 'linkedBy must be a plain name';
		}
		$fldFlaw = self::checkFieldsSet($childSetting['fieldSet'], false);
		if( $fldFlaw!=='' ){
			return 'fieldSet '.$fldFlaw;
		}
		$sortFld = is_string($childSetting['sortedBy']) ? ltrim($childSetting['sortedBy'], '^') : null;
		if( $sortFld===null || ( $sortFld!=='' && !isset($childSetting['fieldSet'][$sortFld]) && $sortFld!==$childSetting['linkedBy'] ) ){
			return 'sortedBy must be one of its fields, ^ before it for the reverse order, or empty';
		}
		if( !is_bool($childSetting['ownRoute']) || !is_bool($childSetting['listsToo']) ){
			return 'ownRoute and listsToo must be true or false';
		}
		return '';
	}

	/**
	 * Proposes the format of a field from the type of its column: a whole
	 * number, a decimal one, a date, a date and time; any other is kept as
	 * sent (OutText is meant for output, not for a value written).
	 *
	 * @param String $columnTypeTx The type of the column, as the database writes it.
	 * @return String The format, '' for a value kept as sent.
	 */
	public static function formatOfColumn( String $columnTypeTx ): String {
		$typeTxt = strtolower(trim($columnTypeTx));
		if( preg_match('/int|serial|bool/', $typeTxt) ){
			return 'Integer';
		}
		if( preg_match('/real|float|double|decimal|numeric/', $typeTxt) ){
			return 'FloatNb';
		}
		if( preg_match('/datetime|timestamp/', $typeTxt) ){
			return 'CustDte(Y-m-d H:i:s)';
		}
		if( preg_match('/^date\b/', $typeTxt) ){
			return 'CustDte(Y-m-d)';
		}
		return '';
	}

}
